import sys
from collections import defaultdict

def solve():
    input = sys.stdin.read().split()
    ptr = 0
    N, M = int(input[ptr]), int(input[ptr+1])
    ptr += 2
    G, S = int(input[ptr]), int(input[ptr+1])
    ptr += 2

    roads = []
    for _ in range(M):
        x, y, g, s = int(input[ptr]), int(input[ptr+1]), int(input[ptr+2]), int(input[ptr+3])
        roads.append((x-1, y-1, g, s))
        ptr += 4

    min_cost = float('inf')

    def is_connected(a, b):
        visited = [False] * N
        stack = [a]
        visited[a] = True
        while stack:
            u = stack.pop()
            if u == b:
                return True
            for (x, y, g, s) in roads:
                if (x == u and g <= a and s <= b) or (y == u and g <= a and s <= b):
                    v = y if x == u else x
                    if not visited[v]:
                        visited[v] = True
                        stack.append(v)
        return False

    def check(a, b):
        for i in range(N):
            for j in range(i+1, N):
                if not is_connected(i, j):
                    return False
        return True

    low = 0
    high = 10**9 + 1
    best_a = 0
    best_b = 0

    while low <= high:
        mid_a = (low + high) // 2
        low_b = 0
        high_b = 10**9 + 1
        best_b_for_a = 0
        found = False
        while low_b <= high_b:
            mid_b = (low_b + high_b) // 2
            if check(mid_a, mid_b):
                best_b_for_a = mid_b
                found = True
                high_b = mid_b - 1
            else:
                low_b = mid_b + 1
        if found:
            best_a = mid_a
            best_b = best_b_for_a
            high = mid_a - 1
        else:
            low = mid_a + 1

    if best_a == 0 and best_b == 0:
        print(-1)
    else:
        print(best_a * G + best_b * S)

solve()
